UPDATE t_order
SET status       = 5,
    update_time  = now(),
    creating_lock=null
WHERE order_id = #{orderId}
  AND status IN (0, 1);

UPDATE t_order
SET status      = 4,
    update_time = now()
WHERE order_id = #{orderId}
  AND status IN (2, 3);

UPDATE t_order
SET status      = 5,
    update_time = now()
WHERE order_id = #{orderId}
  AND status = 4;

UPDATE t_order
SET status      = 3,
    update_time = now()
WHERE order_id = #{orderId}
  AND status = 2;
